# Inputs for the Let's Be Rational fixture, evaluated by the reference
# harness (argv[1]); writes the sexp fixture to stdout.
import math, random, subprocess, sys
random.seed(20261003)
ref = sys.argv[1]
def run(lines):
    out = subprocess.run([ref], input="\n".join(lines) + "\n", capture_output=True, text=True).stdout
    return out.split()
cases = []
for _ in range(300):
    x = random.uniform(-40, 40); s = math.exp(random.uniform(math.log(1e-3), math.log(20)))
    cases.append(("nbc", [x, s]))
# Each region of the normalised Black function, so its expansions are pinned:
# region 2, the small-t expansion (s/2 < 0.21, h = x/s above -10) ...
for _ in range(200):
    s = random.uniform(1e-3, 0.42); x = -10 * s * random.random()
    cases.append(("nbc", [x if random.random() < 0.8 else -x, s]))
# ... and region 1, the asymptotic expansion (h < -10, t small enough).
for _ in range(150):
    s = math.exp(random.uniform(math.log(1e-3), math.log(5))); x = -s * random.uniform(10.3, 40)
    cases.append(("nbc", [x, s]))
for _ in range(100):
    cases.append(("erfcx", [random.uniform(-26, 40)]))
    cases.append(("ncdf", [random.uniform(-38, 8)]))
blacks = []
for _ in range(250):
    F = 100.0; sig = math.exp(random.uniform(math.log(0.005), math.log(3)))
    T = math.exp(random.uniform(math.log(1 / 365), math.log(30)))
    z = random.uniform(-8, 8); K = F * math.exp(-z * sig * math.sqrt(T)); q = random.choice([1.0, -1.0])
    blacks.append(("black", [F, K, sig, T, q]))
cases += blacks
prices = run(["black " + " ".join(repr(a) for a in args) for _, args in blacks])
for (_, (F, K, sig, T, q)), p in zip(blacks, prices):
    cases.append(("iv", [float(p), F, K, T, q]))
results = run([op + " " + " ".join(repr(a) for a in args) for op, args in cases])
def lisp(v):
    if v in ("inf", "-inf"):
        return ":infinity" if v == "inf" else ":-infinity"
    return repr(float(v)).replace("e", "d") if "e" in repr(float(v)) else repr(float(v)) + "d0"
print(";;;; lets-be-rational.sexp --- generated by tests/fixtures/lets-be-rational/generate.sh")
print(";;;; (op (arguments...) expected), from Peter Jäckel's reference C++.")
for (op, args), r in zip(cases, results):
    print(f"(:{op} ({' '.join(lisp(repr(a)) for a in args)}) {lisp(r)})")
